import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3, 4]
    names = ["Arnold", "Eric", "Peter", "Alice"]
    occupations = ["doctor", "engineer", "artist", "teacher"]

    solutions = []

    for name_perm in permutations(names):
        pos_name = {name: idx for idx, name in enumerate(name_perm)}  # 0-based index for houses

        # Clue 1: There are two houses between Eric and Peter. => distance 3 in 0-based
        if abs(pos_name["Eric"] - pos_name["Peter"]) != 3:
            continue

        # Clue 3: Peter is not in the first house.
        if pos_name["Peter"] == 0:
            continue

        for occ_perm in permutations(occupations):
            # Build occupation positions
            pos_occ = {occ: idx for idx, occ in enumerate(occ_perm)}

            # Clue 2: The person who is a teacher is Peter.
            if occ_perm[pos_name["Peter"]] != "teacher":
                continue

            # Clue 5: The person who is an artist is Alice.
            if occ_perm[pos_name["Alice"]] != "artist":
                continue

            # Clue 4: There is one house between the person who is a doctor and Alice.
            if abs(pos_occ["doctor"] - pos_name["Alice"]) != 2:
                continue

            solutions.append((name_perm, occ_perm))

    if not solutions:
        raise ValueError("No solution found.")

    # Assuming unique solution
    name_sol, occ_sol = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Occupation"],
            "rows": [
                [str(i + 1), name_sol[i], occ_sol[i]] for i in range(len(houses))
            ]
        }
    }
    return result

if __name__ == "__main__":
    solution = solve_puzzle()
    print(json.dumps(solution, ensure_ascii=False))
